const DataForwarderSchema = z
  .object({
    organization_id: z
      .int()
      .openapi({ description: 'The ID of the organization related to the data forwarder.' }),
    provider: z
      .enum(['segment', 'sqs', 'splunk'])
      .openapi({
        description:
          'The provider of the data forwarder. One of "segment", "sqs", or "splunk".\n\n* `segment` - Segment\n* `sqs` - Amazon SQS\n* `splunk` - Splunk',
      }),
    is_enabled: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({ description: 'Whether the data forwarder is enabled.' }),
    enroll_new_projects: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description: "Whether to enroll new projects automatically, after they're created.",
      }),
    config: z
      .record(z.string(), z.string())
      .exactOptional()
      .openapi({
        description:
          "The configuration for the data forwarder, specific to the provider type. \nFor a 'sqs' provider, the required keys are queue_url, region, access_key, secret_key. If using a FIFO queue, you must also provide a message_group_id, though s3_bucket is optional. \nFor a 'segment' provider, the required keys are write_key. \nFor a 'splunk' provider, the required keys are instance_url, index, source, token.",
      }),
    project_ids: z
      .array(z.int())
      .exactOptional()
      .openapi({
        description:
          'The IDs of the projects connected to the data forwarder. Missing project IDs will be unenrolled if previously enrolled.',
      }),
  })
  .openapi({ required: ['organization_id', 'provider'] })
  .openapi('DataForwarder')

