const OrganizationReleaseSchema = z
  .object({
    ref: z
      .string()
      .max(200)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'An optional commit reference. This is useful if a tagged version has been provided.',
      }),
    url: z
      .url()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'A URL that points to the release. For instance, this can be the path to an online interface to the source code, such as a GitHub URL.',
      }),
    dateReleased: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'An optional date that indicates when the release went live.  If not provided the current time is used.',
      }),
    commits: z
      .array(
        z
          .object({
            id: z.string().max(64),
            repository: z.string().max(64).nullable().exactOptional(),
            message: z.string().nullable().exactOptional(),
            author_name: z.string().max(128).nullable().exactOptional(),
            author_email: z.string().max(200).nullable().exactOptional(),
            timestamp: z.iso.datetime({ offset: true }).nullable().exactOptional(),
            patch_set: z
              .array(
                z
                  .object({ path: z.string().max(510), type: z.string().max(1) })
                  .openapi({ required: ['path', 'type'] }),
              )
              .nullable()
              .exactOptional(),
          })
          .openapi({ required: ['id'] }),
      )
      .exactOptional()
      .openapi({
        description:
          'An optional list of commit data to be associated. Very long lists are truncated to the most recent commits.',
      }),
    status: z
      .string()
      .exactOptional()
      .openapi({ description: 'The status of the release. Can be `open` or `archived`.' }),
    headCommits: z
      .array(
        z
          .object({
            currentId: z.string().max(64),
            repository: z.string().max(64),
            previousId: z.string().max(64).nullable().exactOptional(),
          })
          .openapi({ required: ['currentId', 'repository'] }),
      )
      .exactOptional()
      .openapi({
        description: 'Deprecated, use `commits`. Head commits to associate with the release.',
      }),
    refs: z
      .array(
        z
          .object({
            commit: z.string(),
            repository: z.string().max(200),
            previousCommit: z.string().max(64).nullable().exactOptional(),
          })
          .openapi({ required: ['commit', 'repository'] }),
      )
      .exactOptional()
      .openapi({
        description:
          "An optional way to indicate the start and end commits for each repository included in a release. Head commits must include parameters ``repository`` and ``commit`` (the HEAD SHA). For GitLab repositories, please use the Group name instead of the slug. They can optionally include ``previousCommit`` (the SHA of the HEAD of the previous release), which should be specified if this is the first time you've sent commit data.",
      }),
  })
  .openapi({ required: [] })
  .openapi('OrganizationRelease')

