const ProjectSizeStatusCheckRulesResponseSchema: z.ZodType<ProjectSizeStatusCheckRulesResponseType> =
  z
    .object({
      enabled: z
        .boolean()
        .openapi({ description: 'Whether size status checks are enabled for the project' }),
      rules: z
        .array(
          z
            .object({
              id: z.string().openapi({ description: 'ID of the rule' }),
              metric: z
                .enum(['install_size', 'download_size'])
                .openapi({
                  description: 'Size metric the rule checks: install_size or download_size',
                }),
              measurement: z
                .enum(['absolute', 'absolute_diff', 'relative_diff'])
                .openapi({
                  description:
                    'How the rule measures size: absolute (size in bytes), absolute_diff (increase in bytes) or relative_diff (increase in percent)',
                }),
              value: z
                .string()
                .openapi({
                  description:
                    'Threshold that makes the status check fail, in bytes or percent depending on measurement',
                }),
              filterQuery: z
                .string()
                .openapi({
                  description: 'Search query that selects the builds the rule applies to',
                }),
              filters: z
                .array(
                  z
                    .object({
                      key: z
                        .enum([
                          'app_id',
                          'build_configuration_name',
                          'git_head_ref',
                          'platform_name',
                        ])
                        .openapi({
                          description:
                            'Build field the filter checks: app_id, build_configuration_name, git_head_ref or platform_name',
                        }),
                      conditions: z
                        .array(
                          z
                            .object({
                              operator: z
                                .enum([
                                  'contains',
                                  'endsWith',
                                  'equals',
                                  'in',
                                  'matches',
                                  'notContains',
                                  'notEndsWith',
                                  'notEquals',
                                  'notIn',
                                  'notMatches',
                                  'notStartsWith',
                                  'startsWith',
                                ])
                                .openapi({
                                  description:
                                    "How the condition compares the build's value, such as equals or startsWith",
                                }),
                              values: z
                                .array(z.string())
                                .openapi({ description: 'Values the condition compares against' }),
                            })
                            .openapi({ required: ['operator', 'values'] }),
                        )
                        .openapi({ description: 'Conditions on the field' }),
                    })
                    .openapi({ required: ['conditions', 'key'] }),
                )
                .nullable()
                .openapi({
                  description:
                    "filterQuery parsed into filters. Null when the query can't be parsed",
                }),
              artifactType: z
                .enum([
                  'main_artifact',
                  'watch_artifact',
                  'android_dynamic_feature_artifact',
                  'app_clip_artifact',
                  'all_artifacts',
                ])
                .openapi({
                  description:
                    'Components the rule applies to, such as main_artifact or all_artifacts',
                }),
            })
            .openapi({
              required: [
                'artifactType',
                'filterQuery',
                'filters',
                'id',
                'measurement',
                'metric',
                'value',
              ],
            }),
        )
        .openapi({ description: 'Rules that make the size status check fail' }),
    })
    .openapi({ required: ['enabled', 'rules'] })
    .openapi('ProjectSizeStatusCheckRulesResponse')

