                'mach_code',
                'elf_debug',
                'elf_code',
                'wasm_debug',
                'wasm_code',
                'breakpad',
                'sourcebundle',
                'uuidmap',
                'bcsymbolmap',
                'il2cpp',
                'proguard',
                'dartsymbolmap',
