export const deleteOrganizationsOrganizationIdOrSlugDetectorsDetectorIdIndexRoute = createRoute({
  method: 'delete',
  path: '/organizations/{organization_id_or_slug}/detectors/{detector_id}/',
  tags: ['Monitors'],
  summary: 'Delete a Monitor',
  description: 'Delete a monitor',
  operationId: 'deleteOrganizationDetector',
  request: {
    params: z.object({
      organization_id_or_slug: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'organization_id_or_slug',
            schema: { type: 'string' },
            description: 'The ID or slug of the organization the resource belongs to.',
            required: true,
          },
        }),
      detector_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            in: 'path',
            name: 'detector_id',
            schema: { type: 'integer' },
            description: "The ID of the monitor you'd like to query.",
            required: true,
          },
        }),
    }),
  },
  responses: {
    204: { description: 'No Content' },
    403: { description: 'Forbidden' },
    404: { description: 'Not Found' },
  },
  security: [{ auth_token: ['alerts:write', 'org:admin', 'org:read', 'org:write'] }],
})

