                  'configData',
                  'configOrganization',
                  'domainName',
                  'externalId',
                  'gracePeriodEnd',
                  'icon',
                  'id',
                  'missingFeatures',
                  'name',
                  'organizationId',
                  'organizationIntegrationStatus',
                  'outOfDate',
                  'provider',
                  'scopes',
