export const deleteOrganizationsOrganizationIdOrSlugIssuesIndexRoute = createRoute({
  method: 'delete',
  path: '/organizations/{organization_id_or_slug}/issues/',
  tags: ['Events'],
  summary: "Bulk Remove an Organization's Issues",
  description:
    "Permanently remove the given issues. If IDs are provided, queries and filtering will be ignored. If any IDs are out of scope, the data won't be mutated but the endpoint will still produce a successful response. For example, if no issues were found matching the criteria, a HTTP 204 is returned.",
  operationId: 'deleteOrganizationIssues',
  request: {
    params: z.object({
      organization_id_or_slug: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'organization_id_or_slug',
            schema: { type: 'string' },
            description: 'The ID or slug of the organization the resource belongs to.',
            required: true,
          },
        }),
    }),
    query: z.object({
      environment: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'environment',
            schema: { type: 'array', items: { type: 'string' } },
            description: 'The name of environments to filter by.',
            required: false,
          },
        }),
      project: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            ((schema) =>
              z.union([
                z.preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  schema,
                ),
                schema,
              ]))(z.union([z.int(), z.string()])),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'project',
            schema: { type: 'array', items: { anyOf: [{ type: 'integer' }, { type: 'string' }] } },
            description:
              'The IDs or slugs of projects to filter by. Project slugs are unique within each organization. Omit this parameter to include all accessible projects. `-1` is also accepted to include all accessible projects.\nFor example, the following are valid parameters:\n- `/?project=1234&project=56789`\n- `/?project=android&project=javascript-react`\n- `/?project=-1`\n',
            required: false,
          },
        }),
      id: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z.preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int(),
            ),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'id',
            schema: { type: 'array', items: { type: 'integer' } },
            description:
              'The list of issue IDs to be removed. If not provided, it will attempt to remove the first 1000 issues.',
            required: false,
          },
        }),
      statsPeriod: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'statsPeriod',
            schema: { type: 'string' },
            description:
              'The period of time for the query, will override the start & end parameters, a number followed by one of:\n- `d` for days\n- `h` for hours\n- `m` for minutes\n- `s` for seconds\n- `w` for weeks\n\nFor example, `24h`, to mean query data starting from 24 hours ago to now.',
            required: false,
          },
        }),
      start: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'start',
            schema: { type: 'string', format: 'date-time' },
            description:
              'The start of the period of time for the query, expected in ISO-8601 format. For example, `2001-12-14T12:34:56.7890`.',
            required: false,
          },
        }),
      end: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'end',
            schema: { type: 'string', format: 'date-time' },
            description:
              'The end of the period of time for the query, expected in ISO-8601 format. For example, `2001-12-14T12:34:56.7890`.',
            required: false,
          },
        }),
      query: z
        .string()
        .default('is:unresolved')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'query',
            schema: { type: 'string', default: 'is:unresolved' },
            description:
              'An optional search query for filtering issues. A default query will apply if no query is set. For all results use this parameter with an empty string.',
            required: false,
          },
        }),
      sort: z
        .enum(['date', 'freq', 'inbox', 'new', 'recommended', 'trends', 'user'])
        .default('date')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'sort',
            schema: {
              type: 'string',
              enum: ['date', 'freq', 'inbox', 'new', 'recommended', 'trends', 'user'],
              default: 'date',
            },
            description:
              "The sort order of the view. Options include 'Last Seen' (`date`), 'First Seen' (`new`), 'Trends' (`trends`), 'Events' (`freq`), 'Users' (`user`), 'Date Added' (`inbox`), and 'Recommended' (`recommended`).",
            required: false,
          },
        }),
    }),
  },
  responses: {
    204: { description: 'No Content' },
    400: { description: 'Bad Request' },
    401: { description: 'Unauthorized' },
    403: { description: 'Forbidden' },
    404: { description: 'Not Found' },
  },
  security: [{ auth_token: ['event:admin'] }],
})

