export const deleteOrganizationsOrganizationIdOrSlugMembersMemberIdIndexRoute = createRoute({
  method: 'delete',
  path: '/organizations/{organization_id_or_slug}/members/{member_id}/',
  tags: ['Organizations'],
  summary: 'Delete an Organization Member',
  description: 'Remove an organization member.',
  operationId: 'deleteOrganizationMember',
  request: {
    params: z.object({
      organization_id_or_slug: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'organization_id_or_slug',
            schema: { type: 'string' },
            description: 'The ID or slug of the organization the resource belongs to.',
            required: true,
          },
        }),
      member_id: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'member_id',
            schema: { type: 'string' },
            description: 'The ID of the member to delete.',
            required: true,
          },
        }),
    }),
  },
  responses: {
    204: { description: 'No Content' },
    400: { description: 'Bad Request' },
    401: { description: 'Unauthorized' },
    403: { description: 'Forbidden' },
    404: { description: 'Not Found' },
  },
  security: [{ auth_token: ['member:admin', 'member:read', 'member:write'] }],
})

export const putOrganizationsOrganizationIdOrSlugMembersMemberIdTeamsTeamIdOrSlugIndexRoute =
  createRoute({
    method: 'put',
    path: '/organizations/{organization_id_or_slug}/members/{member_id}/teams/{team_id_or_slug}/',
    tags: ['Teams'],
    summary: "Update an Organization Member's Team Role",
    description:
      'The relevant organization member must already be a part of the team.\n\nNote that for organization admins, managers, and owners, they are\nautomatically granted a minimum team role of `admin` on all teams they\nare part of. Read more about [team roles](https://docs.sentry.io/product/teams/roles/).',
    operationId: 'updateOrganizationMemberTeam',
    request: {
      params: z.object({
        organization_id_or_slug: z
          .string()
          .openapi({
            param: {
              in: 'path',
              name: 'organization_id_or_slug',
              schema: { type: 'string' },
              description: 'The ID or slug of the organization the resource belongs to.',
              required: true,
            },
          }),
        member_id: z
          .string()
          .openapi({
            param: {
              in: 'path',
              name: 'member_id',
              schema: { type: 'string' },
              description: 'The ID of the organization member to change',
              required: true,
            },
          }),
        team_id_or_slug: z
          .string()
          .openapi({
            param: {
              in: 'path',
              name: 'team_id_or_slug',
              schema: { type: 'string' },
              description: 'The ID or slug of the team the resource belongs to.',
              required: true,
            },
          }),
      }),
      body: {
        content: {
          'application/json': {
            schema: z
              .object({
                teamRole: z
                  .enum(['contributor', 'admin'])
                  .default('contributor')
                  .exactOptional()
                  .openapi({
                    description:
                      "The team-level role to switch to. Valid roles include:\n\n* `contributor` - Contributors can view and act on events, as well as view most other data within the team's projects.\n* `admin` - Admin privileges on the team. They can create and remove projects, and can manage the team's memberships.",
                  }),
              })
              .openapi({ required: [] }),
          },
        },
      },
    },
    responses: {
      200: {
        description: '',
        content: {
          'application/json': {
            schema: z
              .object({
                isActive: z
                  .boolean()
                  .openapi({
                    description:
                      "Whether the team membership is active. An inactive membership removes the team from the member's default list, but the member can rejoin without a request",
                  }),
                teamRole: z
                  .enum(['contributor', 'admin'])
                  .openapi({ description: "ID of the member's team role" }),
              })
              .openapi({ required: ['isActive', 'teamRole'] }),
            examples: {
              UpdateATeamRole: {
                summary: 'Update a Team Role',
                value: { isActive: true, teamRole: 'admin' },
              },
            },
          },
        },
      },
      400: { description: 'Bad Request' },
      404: { description: 'Not Found' },
    },
    security: [
      {
        auth_token: [
          'member:admin',
          'member:read',
          'member:write',
          'org:admin',
          'org:read',
          'org:write',
          'team:admin',
          'team:write',
        ],
      },
    ],
  })

