export const deleteOrganizationsOrganizationIdOrSlugMonitorsMonitorIdOrSlugIndexRoute = createRoute(
  {
    method: 'delete',
    path: '/organizations/{organization_id_or_slug}/monitors/{monitor_id_or_slug}/',
    tags: ['Crons'],
    summary: 'Delete a Monitor or Monitor Environments',
    description: 'Delete a monitor or monitor environments.',
    operationId: 'deleteOrganizationMonitor',
    request: {
      params: z.object({
        organization_id_or_slug: z
          .string()
          .openapi({
            param: {
              in: 'path',
              name: 'organization_id_or_slug',
              schema: { type: 'string' },
              description: 'The ID or slug of the organization the resource belongs to.',
              required: true,
            },
          }),
        monitor_id_or_slug: z
          .string()
          .openapi({
            param: {
              in: 'path',
              name: 'monitor_id_or_slug',
              schema: { type: 'string' },
              description: 'The ID or slug of the monitor.',
              required: true,
            },
          }),
      }),
      query: z.object({
        environment: z
          .preprocess(
            (val) => (val === undefined || Array.isArray(val) ? val : [val]),
            z.array(z.string()),
          )
          .exactOptional()
          .openapi({
            param: {
              in: 'query',
              name: 'environment',
              schema: { type: 'array', items: { type: 'string' } },
              description: 'The name of environments to filter by.',
              required: false,
            },
          }),
      }),
    },
    responses: {
      202: { description: 'Accepted' },
      401: { description: 'Unauthorized' },
      403: { description: 'Forbidden' },
      404: { description: 'Not Found' },
    },
    security: [{ auth_token: ['alerts:write', 'project:admin', 'project:write'] }],
  },
)

