export const getOrganizationsOrganizationIdOrSlugPreprodartifactsSnapshotsLatestBaseIndexRoute =
  createRoute({
    method: 'get',
    path: '/organizations/{organization_id_or_slug}/preprodartifacts/snapshots/latest-base/',
    tags: ['Snapshots'],
    summary: 'Retrieve latest base Snapshot',
    description:
      'Retrieve the most recent base snapshot for a given app.\n\nA base snapshot is one uploaded without a `base_sha` (i.e., a snapshot\nfrom a base branch like `main`). Use the optional `branch` and `project`\nparameters to narrow the search.\n\nThe response includes the full image list with download URLs. Use\n`compact_metadata=1` to reduce image metadata.\n\nThis endpoint requires a bearer token with `project:read` access.',
    operationId: 'getOrganizationPreprodArtifactSnapshotLatestBase',
    request: {
      params: z.object({
        organization_id_or_slug: z
          .string()
          .openapi({
            param: {
              in: 'path',
              name: 'organization_id_or_slug',
              schema: { type: 'string' },
              description: 'The ID or slug of the organization the resource belongs to.',
              required: true,
            },
          }),
      }),
      query: z.object({
        app_id: z
          .string()
          .openapi({
            param: {
              in: 'query',
              name: 'app_id',
              schema: { type: 'string' },
              description: 'App identifier to match.',
              required: true,
            },
          }),
        branch: z
          .string()
          .exactOptional()
          .openapi({
            param: {
              in: 'query',
              name: 'branch',
              schema: { type: 'string' },
              description: 'Git branch name to filter on.',
              required: false,
            },
          }),
        project: ((schema) =>
          z.union([
            z.preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              schema,
            ),
            schema,
          ]))(z.union([z.int(), z.string()]))
          .exactOptional()
          .openapi({
            param: {
              in: 'query',
              name: 'project',
              schema: { anyOf: [{ type: 'integer' }, { type: 'string' }] },
              description: 'Project ID or slug to scope the lookup.',
              required: false,
            },
          }),
        compact_metadata: z
          .string()
          .exactOptional()
          .openapi({
            param: {
              in: 'query',
              name: 'compact_metadata',
              schema: { type: 'string' },
              description:
                "Set to '1' or 'true' to strip image metadata to display_name, image_file_name, group, description, and image_url only.",
              required: false,
            },
          }),
      }),
    },
    responses: {
      200: {
        description: '',
        content: {
          'application/json': {
            schema: z
              .object({
                head_artifact_id: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'ID of the build the snapshot belongs to' }),
                project_id: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'ID of the project' }),
                project_slug: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'Slug of the project' }),
                app_id: z
                  .string()
                  .nullable()
                  .exactOptional()
                  .openapi({ description: 'App identifier of the build' }),
                image_count: z
                  .int()
                  .exactOptional()
                  .openapi({ description: 'Number of images in the snapshot' }),
                images: z
                  .array(
                    z
                      .object({
                        key: z
                          .string()
                          .exactOptional()
                          .openapi({ description: 'Content hash of the image' }),
                        display_name: z
                          .string()
                          .nullable()
                          .exactOptional()
                          .openapi({ description: 'Display name of the image' }),
                        group: z
                          .string()
                          .nullable()
                          .exactOptional()
                          .openapi({ description: 'Group the image belongs to' }),
                        image_file_name: z
                          .string()
                          .exactOptional()
                          .openapi({
                            description:
                              'File name of the image, which identifies it within the snapshot',
                          }),
                        width: z
                          .int()
                          .exactOptional()
                          .openapi({ description: 'Width of the image in pixels' }),
                        height: z
                          .int()
                          .exactOptional()
                          .openapi({ description: 'Height of the image in pixels' }),
                        canvas_theme: z
                          .union([z.literal('light'), z.literal('dark'), z.literal(null)])
                          .nullable()
                          .exactOptional()
                          .openapi({
                            description: 'Theme the image was rendered with: light or dark',
                          }),
                        image_url: z
                          .string()
                          .exactOptional()
                          .openapi({ description: 'API URL to download the image' }),
                      })
                      .openapi({ required: [] }),
                  )
                  .exactOptional()
                  .openapi({ description: 'Images in the snapshot' }),
                diff_threshold: z
                  .float64()
                  .nullable()
                  .exactOptional()
                  .openapi({
                    description:
                      'Fraction of changed pixels, from 0 to 1, above which an image counts as changed. Images can override it',
                  }),
                date_added: z.iso
                  .datetime({ offset: true })
                  .exactOptional()
                  .openapi({ description: 'When the build was uploaded (ISO 8601)' }),
                vcs_info: z
                  .object({
                    head_sha: z
                      .string()
                      .nullable()
                      .exactOptional()
                      .openapi({ description: 'Commit SHA of the build' }),
                    base_sha: z
                      .string()
                      .nullable()
                      .exactOptional()
                      .openapi({
                        description: 'Commit SHA of the base. Empty or null for base snapshots',
                      }),
                    head_ref: z
                      .string()
                      .regex(
                        /^(?:(?!\/)(?!.*\/$)(?!.*\.$)(?!.*\/\/)(?!.*\.\.)(?!(?:.*\/)?\.)(?!.*\.lock(?:\/|$))(?!.*@\{)(?!@$)[^\x00-\x20\x7f~^:?*\[\\]+)?$/,
                      )
                      .max(255)
                      .nullable()
                      .exactOptional()
                      .openapi({ description: 'Branch or ref of the build' }),
                    base_ref: z
                      .string()
                      .regex(
                        /^(?:(?!\/)(?!.*\/$)(?!.*\.$)(?!.*\/\/)(?!.*\.\.)(?!(?:.*\/)?\.)(?!.*\.lock(?:\/|$))(?!.*@\{)(?!@$)[^\x00-\x20\x7f~^:?*\[\\]+)?$/,
                      )
                      .max(255)
                      .nullable()
                      .exactOptional()
                      .openapi({ description: 'Branch or ref of the base' }),
                    head_repo_name: z
                      .string()
                      .nullable()
                      .exactOptional()
                      .openapi({ description: 'Repository name of the build' }),
                    pr_number: z
                      .int()
                      .nullable()
                      .exactOptional()
                      .openapi({ description: 'Pull request number' }),
                  })
                  .exactOptional()
                  .openapi({ description: 'Version control details of the build', required: [] }),
              })
              .openapi({ required: [] }),
            examples: {
              LatestBaseSnapshot: {
                summary: 'Latest Base Snapshot',
                value: {
                  head_artifact_id: '99',
                  project_id: '1',
                  project_slug: 'my-project',
                  app_id: 'com.example.app',
                  image_count: 2,
                  images: [
                    {
                      key: 'a1b2c3d4e5f6',
                      display_name: 'Home Screen',
                      group: 'iPhone 15',
                      image_file_name: 'home_screen_iphone15.png',
                      width: 1170,
                      height: 2532,
                      canvas_theme: 'dark',
                      image_url: '/api/0/projects/org-slug/my-project/files/images/a1b2c3d4e5f6/',
                    },
                  ],
                  diff_threshold: 0.01,
                  date_added: '2025-01-15T10:30:00+00:00',
                  vcs_info: {
                    head_sha: 'abc123def456',
                    base_sha: null,
                    head_ref: 'main',
                    base_ref: null,
                    head_repo_name: 'org/repo',
                    pr_number: null,
                  },
                },
              },
            },
          },
        },
      },
      400: { description: 'Bad Request' },
      403: { description: 'Forbidden' },
      404: { description: 'Not Found' },
    },
    security: [
      {
        auth_token: [
          'org:ci',
          'project:admin',
          'project:read',
          'project:releases',
          'project:write',
        ],
      },
    ],
  })

