export const deleteOrganizationsOrganizationIdOrSlugReleasesVersionIndexRoute = createRoute({
  method: 'delete',
  path: '/organizations/{organization_id_or_slug}/releases/{version}/',
  tags: ['Releases'],
  summary: "Delete an Organization's Release",
  description: 'Permanently remove a release and all of its files.',
  operationId: 'deleteOrganizationRelease',
  request: {
    params: z.object({
      organization_id_or_slug: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'organization_id_or_slug',
            schema: { type: 'string' },
            description: 'The ID or slug of the organization the resource belongs to.',
            required: true,
          },
        }),
      version: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'version',
            schema: { type: 'string' },
            description: 'The version identifier of the release',
            required: true,
          },
        }),
    }),
  },
  responses: {
    204: { description: 'No Content' },
    400: { description: 'Bad Request' },
    401: { description: 'Unauthorized' },
    403: { description: 'Forbidden' },
    404: { description: 'Not Found' },
  },
  security: [{ auth_token: ['project:admin', 'project:releases'] }],
})

