export const postOrganizationsOrganizationIdOrSlugStarredServiceSpansIndexRoute = createRoute({
  method: 'post',
  path: '/organizations/{organization_id_or_slug}/starred-service-spans/',
  tags: ['Explore'],
  summary: 'Star a Service Span',
  description:
    '**Experimental:** This API is under active development and may change.\n\nStar a service span for the requesting user. Span queries expose this as the\n`is_starred_transaction` field. Returns `403` if the user has already starred\nthe service span.',
  operationId: 'starOrganizationServiceSpan',
  request: {
    params: z.object({
      organization_id_or_slug: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'organization_id_or_slug',
            schema: { type: 'string' },
            description: 'The ID or slug of the organization the resource belongs to.',
            required: true,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              service_span: z
                .string()
                .openapi({ description: 'The name of the service span to star or unstar.' }),
              project_id: z
                .int()
                .min(1)
                .openapi({ description: 'The ID of the project the service span belongs to.' }),
            })
            .openapi({ required: ['project_id', 'service_span'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: { description: 'Success' },
    400: { description: 'Bad Request' },
    401: { description: 'Unauthorized' },
    403: { description: 'Forbidden' },
    404: { description: 'Not Found' },
  },
  security: [{ auth_token: ['member:read', 'member:write'] }],
})

export const deleteOrganizationsOrganizationIdOrSlugStarredServiceSpansIndexRoute = createRoute({
  method: 'delete',
  path: '/organizations/{organization_id_or_slug}/starred-service-spans/',
  tags: ['Explore'],
  summary: 'Unstar a Service Span',
  description:
    '**Experimental:** This API is under active development and may change.\n\nUnstar a service span for the requesting user. Succeeds even if the\nservice span was not starred.',
  operationId: 'unstarOrganizationServiceSpan',
  request: {
    params: z.object({
      organization_id_or_slug: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'organization_id_or_slug',
            schema: { type: 'string' },
            description: 'The ID or slug of the organization the resource belongs to.',
            required: true,
          },
        }),
    }),
    query: z.object({
      service_span: z
        .string()
        .openapi({
          param: {
            in: 'query',
            name: 'service_span',
            schema: { type: 'string' },
            description: 'The name of the service span to unstar.',
            required: true,
          },
        }),
      project_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            in: 'query',
            name: 'project_id',
            schema: { type: 'integer' },
            description: 'The ID of the project the service span belongs to.',
            required: true,
          },
        }),
    }),
  },
  responses: {
    200: { description: 'Success' },
    400: { description: 'Bad Request' },
    401: { description: 'Unauthorized' },
    403: { description: 'Forbidden' },
    404: { description: 'Not Found' },
  },
  security: [{ auth_token: ['member:read', 'member:write'] }],
})

