export const deleteOrganizationsOrganizationIdOrSlugWorkflowsIndexRoute = createRoute({
  method: 'delete',
  path: '/organizations/{organization_id_or_slug}/workflows/',
  tags: ['Monitors'],
  summary: 'Bulk Delete Alerts',
  description: 'Bulk delete alerts for a given organization',
  operationId: 'deleteOrganizationWorkflows',
  request: {
    params: z.object({
      organization_id_or_slug: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'organization_id_or_slug',
            schema: { type: 'string' },
            description: 'The ID or slug of the organization the resource belongs to.',
            required: true,
          },
        }),
    }),
    query: z.object({
      query: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'query',
            schema: { type: 'string' },
            description: 'An optional search query for filtering alerts.',
            required: false,
          },
        }),
      id: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z.preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int(),
            ),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'id',
            schema: { type: 'array', items: { type: 'integer' } },
            description: "The ID of the alert you'd like to query.",
            required: false,
          },
        }),
      project: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            ((schema) =>
              z.union([
                z.preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  schema,
                ),
                schema,
              ]))(z.union([z.int(), z.string()])),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'project',
            schema: { type: 'array', items: { anyOf: [{ type: 'integer' }, { type: 'string' }] } },
            description:
              'The IDs or slugs of projects to filter by. Project slugs are unique within each organization. Omit this parameter to include all accessible projects. `-1` is also accepted to include all accessible projects.\nFor example, the following are valid parameters:\n- `/?project=1234&project=56789`\n- `/?project=android&project=javascript-react`\n- `/?project=-1`\n',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: { description: 'Success' },
    204: { description: 'No Content' },
    400: { description: 'Bad Request' },
    401: { description: 'Unauthorized' },
    403: { description: 'Forbidden' },
    404: { description: 'Not Found' },
  },
  security: [{ auth_token: ['alerts:write', 'org:admin', 'org:read', 'org:write'] }],
})

