export const getProjectsOrganizationIdOrSlugProjectIdOrSlugTagsKeyValuesIndexRoute = createRoute({
  method: 'get',
  path: '/projects/{organization_id_or_slug}/{project_id_or_slug}/tags/{key}/values/',
  tags: ['Projects'],
  description:
    'Return a list of values associated with this key.  The `query`\nparameter can be used to to perform a "contains" match on\nvalues. \n\nWhen [paginated](/api/pagination) can return at most 1000 values.',
  operationId: "List a Tag's Values",
  request: {
    params: z.object({
      organization_id_or_slug: z
        .string()
        .openapi({
          param: {
            name: 'organization_id_or_slug',
            in: 'path',
            description: 'The ID or slug of the organization.',
            required: true,
            schema: { type: 'string' },
          },
        }),
      project_id_or_slug: z
        .string()
        .openapi({
          param: {
            name: 'project_id_or_slug',
            in: 'path',
            description: 'The ID or slug of the project.',
            required: true,
            schema: { type: 'string' },
          },
        }),
      key: z
        .string()
        .openapi({
          param: {
            name: 'key',
            in: 'path',
            description: 'The tag key to look up.',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      cursor: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'cursor',
            in: 'query',
            required: false,
            description:
              'A pointer to the last object fetched and its sort order; used to retrieve the next or previous results.',
            'x-learn-more': 'https://docs.sentry.io/api/pagination/',
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                name: z
                  .string()
                  .openapi({
                    description:
                      'The display label of the tag value. For the `sentry:user` tag, the `id:`, `email:`, `username:` or `ip:` prefix is removed.',
                  }),
              })
              .openapi({ required: ['name'] }),
          ),
          example: [{ name: 'mint_choco' }],
        },
      },
    },
    403: { description: 'Forbidden' },
  },
  security: [{ auth_token: ['project:read'] }],
})

