export const putProjectsOrganizationIdOrSlugProjectIdOrSlugIssuesIndexRoute = createRoute({
  method: 'put',
  path: '/projects/{organization_id_or_slug}/{project_id_or_slug}/issues/',
  tags: ['Events'],
  description:
    'Bulk mutate various attributes on issues.  The list of issues to modify is given through the `id` query parameter.  It is repeated for each issue that should be modified.\n\n- For non-status updates, the `id` query parameter is required.\n- For status updates, the `id` query parameter may be omitted\nfor a batch "update all" query.\n- To restrict a batch "update all" to issues with a given status,\nuse the `query` parameter, e.g. `query=is:resolved`.\n\nThe following attributes can be modified and are supplied as JSON object in the body:\n\nIf any IDs are out of scope this operation will succeed without any data mutation.',
  operationId: 'Bulk Mutate a List of Issues',
  request: {
    params: z.object({
      organization_id_or_slug: z
        .string()
        .openapi({
          param: {
            name: 'organization_id_or_slug',
            in: 'path',
            description: 'The ID or slug of the organization the issues belong to.',
            required: true,
            schema: { type: 'string' },
          },
        }),
      project_id_or_slug: z
        .string()
        .openapi({
          param: {
            name: 'project_id_or_slug',
            in: 'path',
            description: 'The ID or slug of the project the issues belong to.',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'id',
            in: 'query',
            description:
              'A list of IDs of the issues to be mutated. This parameter shall be repeated for each issue. It is optional only if a status is mutated in which case an implicit update all is assumed.',
            required: false,
            schema: { type: 'integer' },
          },
        }),
      query: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'query',
            in: 'query',
            description:
              'An optional Sentry structured search query that selects the issues to update when `id` is not provided. If not provided an implied `"is:unresolved"` is assumed. Use `is:<status>` (e.g. `is:resolved`) to limit it to issues with that status.',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              status: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The new status for the issues. Valid values are `"resolved"`, `"resolvedInNextRelease"`, `"unresolved"`, and `"ignored"`.',
                }),
              statusDetails: z
                .object({
                  inRelease: z.string().exactOptional(),
                  inNextRelease: z.boolean().exactOptional(),
                  inCommit: z.string().exactOptional(),
                  ignoreDuration: z.int().exactOptional(),
                  ignoreCount: z.int().exactOptional(),
                  ignoreWindow: z.int().exactOptional(),
                  ignoreUserCount: z.int().exactOptional(),
                  ignoreUserWindow: z.int().exactOptional(),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Additional details about the resolution. Valid values are `"inRelease"`, `"inNextRelease"`, `"inCommit"`, `"ignoreDuration"`, `"ignoreCount"`, `"ignoreWindow"`, `"ignoreUserCount"`, and `"ignoreUserWindow"`.',
                  required: [],
                }),
              ignoreDuration: z
                .int()
                .exactOptional()
                .openapi({ description: 'The number of minutes to ignore this issue.' }),
              isPublic: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Sets the issue to public or private.' }),
              merge: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Allows to merge or unmerge different issues.' }),
              assignedTo: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The actor ID (or username) of the user or team that should be assigned to this issue.',
                }),
              hasSeen: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'In case this API call is invoked with a user context this allows changing of the flag that indicates if the user has seen the event.',
                }),
              isBookmarked: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'In case this API call is invoked with a user context this allows changing of the bookmark flag.',
                }),
            })
            .openapi({ required: [] }),
          example: { isPublic: false, status: 'unresolved' },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Success',
      content: {
        'application/json': {
          schema: z
            .object({
              isPublic: z
                .boolean()
                .openapi({ description: 'Whether the issues are shared publicly.' }),
              status: z
                .enum(['resolved', 'unresolved', 'ignored'])
                .openapi({ description: 'The new status of the issues.' }),
              statusDetails: z
                .object({
                  ignoreCount: z
                    .int()
                    .nullable()
                    .exactOptional()
                    .openapi({
                      description:
                        'Number of additional events after which the issues stop being ignored.',
                    }),
                  ignoreUntil: z.iso
                    .datetime({ offset: true })
                    .nullable()
                    .exactOptional()
                    .openapi({ description: 'When the issues stop being ignored.' }),
                  ignoreUserCount: z
                    .int()
                    .nullable()
                    .exactOptional()
                    .openapi({
                      description:
                        'Number of additional affected users after which the issues stop being ignored.',
                    }),
                  ignoreUserWindow: z
                    .int()
                    .nullable()
                    .exactOptional()
                    .openapi({ description: 'Time window in minutes for ignoreUserCount.' }),
                  ignoreWindow: z
                    .int()
                    .nullable()
                    .exactOptional()
                    .openapi({ description: 'Time window in minutes for ignoreCount.' }),
                  ignoreUntilEscalating: z
                    .boolean()
                    .exactOptional()
                    .openapi({
                      description: 'Whether the issues stay ignored until they escalate.',
                    }),
                  actor: z
                    .object({
                      id: z.string().exactOptional().openapi({ description: 'ID of the user.' }),
                      name: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Name of the user.' }),
                      username: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Username of the user.' }),
                      email: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Email address of the user.' }),
                    })
                    .nullable()
                    .exactOptional()
                    .openapi({
                      description: 'User who ignored or resolved the issues.',
                      required: [],
                    }),
                  inNextRelease: z
                    .boolean()
                    .exactOptional()
                    .openapi({
                      description: 'Whether the issues are resolved in the next release.',
                    }),
                  inRelease: z
                    .string()
                    .exactOptional()
                    .openapi({ description: 'Version of the release the issues are resolved in.' }),
                  inCommit: z
                    .object({
                      id: z.string().exactOptional().openapi({ description: 'Commit SHA.' }),
                      message: z
                        .string()
                        .nullable()
                        .exactOptional()
                        .openapi({ description: 'Commit message.' }),
                      dateCreated: z.iso
                        .datetime({ offset: true })
                        .exactOptional()
                        .openapi({ description: 'When the commit was made.' }),
                    })
                    .exactOptional()
                    .openapi({ description: 'Commit the issues are resolved in.', required: [] }),
                })
                .openapi({
                  description:
                    'Details of the new status, such as the release that resolves the issues or when an ignore expires. Empty when the new status has no details.',
                  required: [],
                }),
            })
            .openapi({ required: ['isPublic', 'status', 'statusDetails'] }),
          example: { isPublic: false, status: 'unresolved', statusDetails: {} },
        },
      },
    },
    400: { description: 'Bad Input' },
    403: { description: 'Forbidden' },
    404: { description: 'The requested resource does not exist' },
  },
  security: [{ auth_token: ['event:write'] }],
})

