export const deleteOrganizationsOrganizationIdOrSlugIssuesIssueIdIntegrationsIntegrationIdIndexRoute =
  createRoute({
    method: 'delete',
    path: '/organizations/{organization_id_or_slug}/issues/{issue_id}/integrations/{integration_id}/',
    tags: ['Integration'],
    description:
      'Remove the link between a Sentry issue and an external issue. If no other\nSentry issues reference the external issue, the link record is deleted\nentirely. An absent link also returns 204. This does not delete the issue\nin the external provider.',
    operationId: 'Unlink an External Issue from an Issue',
    request: {
      params: z.object({
        organization_id_or_slug: z
          .string()
          .openapi({
            param: {
              in: 'path',
              name: 'organization_id_or_slug',
              schema: { type: 'string' },
              description: 'The ID or slug of the organization the resource belongs to.',
              required: true,
            },
          }),
        issue_id: z
          .string()
          .openapi({
            param: {
              in: 'path',
              name: 'issue_id',
              schema: { type: 'string' },
              description: "The ID of the issue you'd like to query.",
              required: true,
            },
          }),
        integration_id: z
          .string()
          .openapi({
            param: {
              in: 'path',
              name: 'integration_id',
              schema: { type: 'string' },
              description: 'The ID of the integration installed on the organization.',
              required: true,
            },
          }),
      }),
      query: z.object({
        externalIssue: z
          .preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            z.int(),
          )
          .openapi({
            param: {
              in: 'query',
              name: 'externalIssue',
              schema: { type: 'integer' },
              description: 'The ID of the `ExternalIssue` link to remove.',
              required: true,
            },
          }),
      }),
    },
    responses: {
      204: { description: 'No Content' },
      400: { description: 'Bad Request' },
      403: { description: 'Forbidden' },
      404: { description: 'Not Found' },
      409: {
        description: '',
        content: {
          'application/json': {
            schema: z
              .object({ detail: z.string() })
              .openapi({
                description:
                  'DRF\'s standard error-body shape: `{"detail": str}`.\n\nUse in `Response[T] | Response[DetailResponse]` annotations on endpoints\nwhose inline error returns are exactly `Response({"detail": "..."}, status=4xx)`.\nEndpoints whose error bodies have richer or different shapes should\ndeclare their own local TypedDicts instead.',
                required: ['detail'],
              }),
          },
        },
      },
    },
    security: [{ auth_token: ['event:admin', 'event:write'] }],
  })

export const getOrganizationsOrganizationIdOrSlugIssuesIssueIdTagsKeyIndexRoute = createRoute({
  method: 'get',
  path: '/organizations/{organization_id_or_slug}/issues/{issue_id}/tags/{key}/',
  tags: ['Events'],
  summary: 'Retrieve Tag Details',
  description:
    'Return a list of values associated with this key for an issue. When paginated can return at most 1000 values.',
  operationId: 'getOrganizationIssueTag',
  request: {
    params: z.object({
      issue_id: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'issue_id',
            schema: { type: 'string' },
            description: "The ID of the issue you'd like to query.",
            required: true,
          },
        }),
      organization_id_or_slug: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'organization_id_or_slug',
            schema: { type: 'string' },
            description: 'The ID or slug of the organization the resource belongs to.',
            required: true,
          },
        }),
      key: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'key',
            schema: { type: 'string' },
            description: 'The tag key to look the values up for.',
            required: true,
          },
        }),
    }),
    query: z.object({
      environment: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'environment',
            schema: { type: 'array', items: { type: 'string' } },
            description: 'The name of environments to filter by.',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              uniqueValues: z
                .int()
                .nullable()
                .exactOptional()
                .openapi({ description: 'Number of distinct values seen for the tag key' }),
              totalValues: z
                .int()
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    "Number of events counted for the tag key. For an issue tag, this is the issue's retained event count, including events without the tag",
                }),
              topValues: z
                .array(
                  z
                    .object({
                      query: z
                        .string()
                        .nullable()
                        .exactOptional()
                        .openapi({
                          description:
                            'Search query that matches events with the tag value. Only set for the user tag',
                        }),
                      key: z
                        .string()
                        .openapi({
                          description:
                            'Tag key, with the `sentry:` prefix removed from built-in keys',
                        }),
                      name: z
                        .string()
                        .nullable()
                        .openapi({
                          description:
                            'Display label of the tag value. For the user tag, the `id:`, `email:`, `username:` or `ip:` prefix is removed',
                        }),
                      value: z.string().nullable().openapi({ description: 'Tag value' }),
                      count: z
                        .int()
                        .nullable()
                        .openapi({
                          description:
                            'Number of events with the tag value. Null for an empty value',
                        }),
                      lastSeen: z.iso
                        .datetime({ offset: true })
                        .nullable()
                        .openapi({
                          description:
                            'When the tag value was last seen (ISO 8601). Null for an empty value',
                        }),
                      firstSeen: z.iso
                        .datetime({ offset: true })
                        .nullable()
                        .openapi({
                          description:
                            'When the tag value was first seen (ISO 8601). Null for an empty value',
                        }),
                    })
                    .openapi({
                      required: ['count', 'firstSeen', 'key', 'lastSeen', 'name', 'value'],
                    }),
                )
                .nullable()
                .exactOptional()
                .openapi({ description: 'Most frequent values of the tag key, ordered by count' }),
              key: z
                .string()
                .openapi({
                  description: 'Tag key, with the `sentry:` prefix removed from built-in keys',
                }),
              name: z.string().openapi({ description: 'Display label of the tag key' }),
            })
            .openapi({ required: ['key', 'name'] }),
          examples: {
            "ReturnASpecificTag'sDetails": {
              summary: "Return a specific tag's details",
              value: {
                key: 'flavors',
                name: 'Flavors',
                uniqueValues: 2,
                totalValues: 3,
                topValues: [
                  {
                    key: 'strawberry',
                    name: 'Strawberry',
                    value: 'strawberry',
                    count: 2,
                    lastSeen: '2024-01-01T00:00:00Z',
                    firstSeen: '2024-01-01T00:00:00Z',
                  },
                  {
                    key: 'vanilla',
                    name: 'Vanilla',
                    value: 'vanilla',
                    count: 1,
                    lastSeen: '2024-01-01T00:00:00Z',
                    firstSeen: '2024-01-01T00:00:00Z',
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: { description: 'Bad Request' },
    401: { description: 'Unauthorized' },
    403: { description: 'Forbidden' },
    404: { description: 'Not Found' },
  },
  security: [{ auth_token: ['event:admin', 'event:read', 'event:write'] }],
})

